 $('#stockTrades').innerHTML=records.slice(0,40).map(r=>`<tr><td><strong>${esc(r.person)}</strong>${typeof ratingBadge==='function'?ratingBadge(r.person):''}<small>${esc(r.owner)}</small></td><td><span class="type-badge ${r.type.toLowerCase()}">${esc(r.type)}</span><small>${esc(r.asset)}</small></td><td><small>${transactionLabel(r)}</small>${date(r.traded)}</td><td><small>Disclosed on</small>${disclosedDate(r)?date(disclosedDate(r)):'Unknown'}<small>${disclosureDelay(r)!==null?disclosureDelay(r)+'d gap':'Signed '+date(r.filed)}</small></td><td>${esc(r.amount)}</td><td><span class="${(priceReturn(r)?.pct||0)>=0?'gain':'loss'}">${priceReturn(r)?percent(priceReturn(r)):'—'}</span><small>since trade${r.asset==='Call options'?' · stock only':''}</small></td><td><button class="row-details" data-detail="${esc(r.id)}">Details</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No political disclosures for this ticker in the loaded feeds.</td></tr>';
